WITH valid AS (SELECT *, CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END AS is_completed FROM orders WHERE channel IS DISTINCT FROM 'store' AND channel IS NOT NULL) SELECT id, store_id, status, channel, amount, discount, shipping_fee, LEAD(discount, 1) OVER (PARTITION BY customer_id, store_id ORDER BY shipping_fee, id) AS next_discount, MAX(amount) OVER (PARTITION BY store_id) AS store_id_max_amount FROM valid;
